const item = $input.first().json;
const html = String(item.html_code || '');
const pageName = String(item.page_name || 'page.html');

const local = [];
if (html.indexOf('joulie-chat') !== -1) local.push('Dead endpoint typo "joulie-chat" found (should be a live endpoint).');
if (html.indexOf('julie-chat') !== -1) local.push('Endpoint "julie-chat" referenced - confirm it is live (known live: deploy-julie, submit-job).');
if (html.indexOf('submit-cv') !== -1) local.push('Endpoint "submit-cv" referenced - confirm it is live.');
if (!/name=["']viewport["']/i.test(html)) local.push('Missing responsive viewport meta tag.');
if (!/<title[>\s]/i.test(html)) local.push('Missing <title> tag (SEO).');
if (!/name=["']description["']/i.test(html)) local.push('Missing meta description (SEO).');
const imgs = html.match(/<img\b[^>]*>/gi) || [];
const imgsNoAlt = imgs.filter(function (t) { return !/\balt=/i.test(t); }).length;
if (imgsNoAlt > 0) local.push(imgsNoAlt + ' <img> tag(s) missing alt attribute (accessibility).');
if (/sk-[A-Za-z0-9]{20,}/.test(html) || /AIza[0-9A-Za-z\-_]{30,}/.test(html)) local.push('Possible exposed API key detected in HTML (security).');
['div', 'section', 'header', 'footer', 'main', 'nav', 'ul', 'ol', 'script', 'style'].forEach(function (tag) {
  const open = (html.match(new RegExp('<' + tag + '\\b', 'gi')) || []).length;
  const close = (html.match(new RegExp('</' + tag + '>', 'gi')) || []).length;
  if (open !== close) local.push('Unbalanced <' + tag + '> tags: ' + open + ' open vs ' + close + ' close (possible truncation/malformed).');
});
const localText = local.length ? local.map(function (l, i) { return (i + 1) + '. ' + l; }).join('\n') : 'No issues found by local static checks.';

const instr = 'You are a meticulous web QA reviewer for the website hsndm.tech. Review the HTML between the <<<HTML>>> markers. Check ALL of: (1) broken/dead endpoints & links - known-bad: "joulie-chat","julie-chat"; known-good live webhooks: "deploy-julie","submit-job"; (2) unbalanced/malformed/truncated tags; (3) SEO & meta tags (title, description, og:); (4) accessibility (alt text, aria, contrast); (5) mobile/responsive; (6) brand/content consistency for hsndm.tech; (7) security (exposed keys, unsafe inline scripts). Respond ONLY with minified JSON, no markdown: {"reviewer":"<NAME>","overall":"pass|warn|fail","issues":[{"category":"...","severity":"high|medium|low","detail":"...","suggestedFix":"..."}]}';

function userMsg(name) {
  return 'Static pre-check findings:\n' + localText + '\n\n<<<HTML>>>\n' + html + '\n<<<HTML>>>';
}
function bodyOpenAI(model, name) {
  return JSON.stringify({ model: model, temperature: 0.2, response_format: { type: 'json_object' }, messages: [ { role: 'system', content: instr.replace('<NAME>', name) }, { role: 'user', content: userMsg(name) } ] });
}
const geminiBody = bodyOpenAI('google/gemini-2.0-flash-001', 'Gemini');

return [{ json: { page_name: pageName, html: html, localText: localText, groqBody: bodyOpenAI('llama-3.3-70b-versatile', 'Groq'), kimiBody: bodyOpenAI('moonshotai/kimi-k2', 'Kimi'), geminiBody: geminiBody } }];

function parseOpenAI(nodeName) {
  try { return JSON.parse($(nodeName).first().json.choices[0].message.content); }
  catch (e) { return { reviewer: nodeName, overall: 'error', issues: [{ category: 'system', severity: 'low', detail: 'Could not parse response: ' + e.message, suggestedFix: '' }] }; }
}
const reviews = [parseOpenAI('Groq Review'), parseOpenAI('Gemini Review'), parseOpenAI('Kimi Review')];
const base = $('Local Pre-Checks').first().json;
const allIssues = [];
reviews.forEach(function (r) { (r.issues || []).forEach(function (i) { allIssues.push({ reviewer: r.reviewer || '?', category: i.category, severity: i.severity, detail: i.detail, suggestedFix: i.suggestedFix }); }); });
const rank = { high: 0, medium: 1, low: 2 };
allIssues.sort(function (a, b) { return (rank[a.severity] == null ? 3 : rank[a.severity]) - (rank[b.severity] == null ? 3 : rank[b.severity]); });
const findingsText = allIssues.length
  ? allIssues.map(function (i, n) { return (n + 1) + '. [' + String(i.severity || '?').toUpperCase() + '] (' + i.reviewer + ' / ' + i.category + ') ' + i.detail + (i.suggestedFix ? (' - Fix: ' + i.suggestedFix) : ''); }).join('\n')
  : 'No issues reported by any reviewer.';

const fixInstr = 'You are an expert front-end engineer. Given the ORIGINAL HTML and a list of QA issues, return the COMPLETE corrected HTML document. Preserve all working integration endpoints (deploy-julie, submit-job) and tokens (SHEET_ID, JULIE_ENDPOINT, SUBMIT_ENDPOINT). Fix any "joulie-chat"/"julie-chat" typos. Do NOT add explanations or markdown fences. Return ONLY raw HTML.';
const fixBody = JSON.stringify({ model: 'moonshotai/kimi-k2', temperature: 0.1, messages: [{ role: 'system', content: fixInstr }, { role: 'user', content: 'QA ISSUES:\n' + findingsText + '\n\nORIGINAL HTML:\n' + base.html }] });

return [{ json: { page_name: base.page_name, html: base.html, findingsText: findingsText, issuesCount: allIssues.length, reviews: reviews, fixBody: fixBody } }];

const base = $('Consolidate Reviews').first().json;
let corrected = '';
try { corrected = String($('Generate Corrected HTML').first().json.choices[0].message.content || ''); } catch (e) { corrected = ''; }
corrected = corrected.replace(/^\s*```html\s*/i, '').replace(/\s*```\s*$/i, '').trim();
function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
const reportHtml = '<div style="font-family:system-ui,sans-serif;max-width:900px;margin:0 auto;padding:24px">'
  + '<h1>QA Review - ' + esc(base.page_name) + '</h1>'
  + '<p><strong>' + base.issuesCount + '</strong> issue(s) found by Groq + Gemini + Kimi working together.</p>'
  + '<h2>Findings</h2><pre style="white-space:pre-wrap;background:#f5f5f5;padding:16px;border-radius:8px">' + esc(base.findingsText) + '</pre>'
  + '<h2>Corrected HTML</h2><p>Copy the code below and paste it into your GitHub file (or check the email sent to you).</p>'
  + '<textarea style="width:100%;height:320px;font-family:monospace">' + esc(corrected) + '</textarea>'
  + '<p style="color:#888;margin-top:24px">No changes were committed to GitHub. Review and deploy manually.</p></div>';
const emailHtml = '<h2>QA Review - ' + esc(base.page_name) + '</h2><p>' + base.issuesCount + ' issue(s) found by Groq + Gemini + Kimi.</p>'
  + '<h3>Findings</h3><pre>' + esc(base.findingsText) + '</pre>'
  + '<h3>Corrected HTML</h3><pre>' + esc(corrected) + '</pre>';
return [{ json: { page_name: base.page_name, reportHtml: reportHtml, emailHtml: emailHtml, correctedHtml: corrected, issuesCount: base.issuesCount } }];
